  const tMinus = jdToAstroTime(jd_ut - dtDays);
  const posPlus = getTropicalLongitude(bodyId, tPlus);
  const posMinus = getTropicalLongitude(bodyId, tMinus);
  let dLon = posPlus.lon - posMinus.lon;
  dLon = ((dLon + 180) % 360 + 360) % 360 - 180;
